import{_ as r,a0 as l,w as s,s as p,ao as u,I as o,x as t,a1 as i,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"Linux 有问必答：在 Linux 如何更改文本文件的字符编码 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有问必答：在 Linux 如何更改文本文件的字符编码 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有问必答：在 Linux 如何更改文本文件的字符编码 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有问必答：在 Linux 如何更改文本文件的字符编码 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141022 Linux FAQs with Answers--How to change character encoding of a text file on Linux","title":"Linux 有问必答：在 Linux 如何更改文本文件的字符编码","tag":"201411","desc":""},"relativePath":"201411/20141022 Linux FAQs with Answers--How to change character encoding of a text file on Linux.md","filePath":"[post].md"}'),x={name:"201411/20141022 Linux FAQs with Answers--How to change character encoding of a text file on Linux.md"};function d(f,e,c,m,h,L){const n=l("Link");return s(),p("div",null,[e[11]||(e[11]=u(`<h1 id="linux-有问必答-在-linux-如何更改文本文件的字符编码" tabindex="-1">Linux 有问必答：在 Linux 如何更改文本文件的字符编码 <a class="header-anchor" href="#linux-有问必答-在-linux-如何更改文本文件的字符编码" aria-label="Permalink to “Linux 有问必答：在 Linux 如何更改文本文件的字符编码”">​</a></h1><blockquote><p><strong>问题</strong>：在我的 Linux 系统中有一个编码为 iso-8859-1 的字幕文件，其中部分字符无法正常显示，我想把文本改为 utf8 编码。在 Linux 中, 有没有一个好的工具来转换文本文件的字符编码？</p></blockquote><p>正如我们所知道的那样，电脑只能够处理低级的二进制值，并不能直接处理字符。当一个文本文件被存储时，文件中的每一个字符都被映射成二进制值，实际存储在硬盘中的正是这些“二进制值”。之后当程序打开文本文件时，所有二进制值都被读入并映射回原始的可读字符。只有当所有需要访问这个文件的程序都能够“理解”它的编码，即二进制值到字符的映射时，这个“保存和打开”的过程才能很好地完成，这也确保了可理解数据的往返过程。</p><p>如果不同的程序使用不同的编码来处理同一个文件，源文件中的特殊字符就无法正常显示。这里的特殊字符指的是非英文字母的字符，例如带重音的字符（比如 ñ，á，ü）。</p><p>然后问题就来了： 1）我们如何确定一个确定的文本文件使用的是什么字符编码？ 2）我们如何把文件转换成已选择的字符编码？</p><h3 id="步骤一" tabindex="-1">步骤一 <a class="header-anchor" href="#步骤一" aria-label="Permalink to “步骤一”">​</a></h3><p>为了确定文件的字符编码，我们使用一个名为 “file” 的命令行工具。因为 file 命令是一个标准的 UNIX 程序，所以我们可以在所有现代的 Linux 发行版中找到它。</p><p>运行下面的命令：</p><pre><code>$ file --mime-encoding filename 
</code></pre><p><img src="https://farm6.staticflickr.com/5602/15595534261_1a7b4d16a2.jpg" alt=""></p><h3 id="步骤二" tabindex="-1">步骤二 <a class="header-anchor" href="#步骤二" aria-label="Permalink to “步骤二”">​</a></h3><p>下一步是查看你的 Linux 系统所支持的文件编码种类。为此，我们使用名为 iconv 的工具及 “-l” 选项（L 的小写）来列出所有当前支持的编码。</p><pre><code>$ iconv -l 
</code></pre><p>iconv 工具是 GNU libc 库组成部分，因此它在所有 Linux 发行版中都是开箱即用的。</p><h3 id="步骤三" tabindex="-1">步骤三 <a class="header-anchor" href="#步骤三" aria-label="Permalink to “步骤三”">​</a></h3><p>在我们在我们的 Linux 系统所支持的编码里面选定了目标编码之后，运行下面的命令来完成编码转换：</p><pre><code>$ iconv -f old_encoding -t new_encoding filename
</code></pre><p>例如，把 iso-8859-1 编码转换为 utf-8 编码：</p><pre><code>$ iconv -f iso-8859-1 -t utf-8 input.txt 
</code></pre><p><img src="https://farm4.staticflickr.com/3943/14978042143_a516e0b10b_o.png" alt=""></p><p>了解了我们演示的如何使用这些工具之后，你可以像下面这样修复一个受损的字幕文件：</p><p><img src="https://farm6.staticflickr.com/5612/15412197967_0dfe5078f9_z.jpg" alt=""></p><hr>`,23)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),i(n,{href:"http://ask.xmodulo.com/change-character-encoding-text-file-linux.html"},{default:a(()=>[...e[0]||(e[0]=[t("http://ask.xmodulo.com/change-character-encoding-text-file-linux.html",-1)])]),_:1})]),o("p",null,[e[4]||(e[4]=t("译者：",-1)),i(n,{href:"https://github.com/wangjiezhe"},{default:a(()=>[...e[2]||(e[2]=[t("wangjiezhe",-1)])]),_:1}),e[5]||(e[5]=t(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:a(()=>[...e[3]||(e[3]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[8]||(e[8]=t("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[6]||(e[6]=[t("LCTT",-1)])]),_:1}),e[9]||(e[9]=t(" 原创翻译，",-1)),i(n,{href:"http://linux.cn/"},{default:a(()=>[...e[7]||(e[7]=[t("Linux中国",-1)])]),_:1}),e[10]||(e[10]=t(" 荣誉推出",-1))])])}const w=r(x,[["render",d]]);export{T as __pageData,w as default};
